INSERT INTO public."Project" (id, code, name, location, owner, administrator, consultant, contractor, objective, "scopeSummary", "startDate", "targetCompletionDate", "targetHandoverDate", "currentPhase", status, health, "overallProgress", "designProgress", "procurementProgress", "constructionProgress", "safetyScore", "contractValue", currency, "createdAt", "updatedAt") VALUES
	('cmsgb1803000j7dqq1hq49505', 'QN-CSL-2026', 'QNITY CSL Laboratory Renovation 2026', 'INC2 Building, Thailand Science Park, Thailand', 'QNITY', 'Warisa Kantifong', 'SYME072', 'Design Alternative', 'Renovate the QNITY Central Science Laboratory (CSL) in the INC2 Building into a modern, compliant analytical facility that supports the 2026 CAPEX equipment programme, improves laboratory safety and containment performance, and is fully handed over to operations on 06 December 2026.', '{"Architectural renovation of the CSL laboratory area including partition, ceiling, flooring and finishing works","New laboratory furniture layout, fume hoods and containment enclosures","HVAC upgrade with dedicated exhaust duct system and pressure cascade control","Electrical, lighting, plumbing, laboratory gas and fire protection system modification","Cleanroom-grade zone for sensitive analytical instrumentation","Installation, commissioning and qualification support for New CAPEX 2026 laboratory equipment","Utility matrix alignment for SEM-EDS, ICP-OES, Ion Chromatography, Autolab and FT230","Documentation, training and handover to QNITY laboratory operations"}', '2026-01-12 00:00:00', '2026-11-30 00:00:00', '2026-12-06 00:00:00', 'Construction', 'In Progress — Construction & Procurement running in parallel', 'YELLOW', 58, 92, 71, 41, 94, 48500000.00, 'THB', '2026-08-05 16:31:47.139', '2026-08-05 16:31:47.139');
