INSERT INTO public."ProjectPhase" (id, "projectId", sequence, name, "plannedStart", "plannedFinish", "actualStart", "actualFinish", status, progress, "plannedProgress", owner, "keyDeliverables", "delayReason", "recoveryPlan", "updatedAt") VALUES
	('cmsgb180i00167dqqora64mbv', 'cmsgb1803000j7dqq1hq49505', 1, 'Initiation', '2026-01-12 00:00:00', '2026-02-27 00:00:00', '2026-01-12 00:00:00', '2026-02-24 00:00:00', 'COMPLETED', 100, 100, 'Warisa Kantifong', '{"Project charter approved","URS issued and approved","SOW approved","Budget CAPEX 2026 confirmed"}', NULL, NULL, '2026-08-05 16:31:47.154'),
	('cmsgb180n00187dqq0tr0sh07', 'cmsgb1803000j7dqq1hq49505', 2, 'Engineering Design', '2026-02-16 00:00:00', '2026-06-30 00:00:00', '2026-02-16 00:00:00', NULL, 'IN_PROGRESS', 92, 100, 'Song Dong', '{"Architectural and laboratory furniture layout approved","HVAC and exhaust duct design approved","Electrical, lighting and plumbing design approved","IFC drawing package released","Utility matrix finalised for CAPEX equipment"}', 'Cleanroom system and gas system packages returned with owner comments in Rev.B; utility matrix waiting on final ICP-OES vendor data sheet.', 'Design Alternative to resubmit Rev.C by 12 Aug 2026. SYME072 committed to a 5-working-day review turnaround to protect the IFC release date.', '2026-08-05 16:31:47.159'),
	('cmsgb180p001a7dqqz705wysr', 'cmsgb1803000j7dqq1hq49505', 3, 'Procurement', '2026-03-02 00:00:00', '2026-09-30 00:00:00', '2026-03-05 00:00:00', NULL, 'IN_PROGRESS', 71, 78, 'Rita Tang', '{"Main contractor award to Design Alternative","CAPEX 2026 equipment purchase orders issued","Long-lead equipment (SEM-EDS, ICP-OES) secured","Laboratory furniture and fume hood vendor confirmed"}', 'SEM-EDS commercial evaluation extended by two weeks due to a scope clarification on the EDS detector package.', 'Leadership approval requested for 08 Aug 2026 to release the SEM-EDS PO and hold the vendor''s 30-week manufacturing slot.', '2026-08-05 16:31:47.161'),
	('cmsgb180r001c7dqq1l4hhzwc', 'cmsgb1803000j7dqq1hq49505', 4, 'Construction', '2026-06-08 00:00:00', '2026-11-13 00:00:00', '2026-06-15 00:00:00', NULL, 'AT_RISK', 41, 50, 'Nattapong Wongsiri', '{"Demolition and site preparation","Partition, ceiling and flooring works","HVAC and exhaust duct installation","Electrical, plumbing and gas line rough-in","Laboratory furniture and fume hood installation","Mechanical completion"}', 'Construction start slipped 7 days waiting on the INC2 building permit endorsement; exhaust duct riser penetration approval from the landlord is still open.', 'Two-shift working approved for the duct installation from 10 Aug 2026. Recovery schedule targets full alignment with the baseline by end of September 2026.', '2026-08-05 16:31:47.163'),
	('cmsgb180s001e7dqqoqtmfu33', 'cmsgb1803000j7dqq1hq49505', 5, 'Commissioning', '2026-10-05 00:00:00', '2026-11-27 00:00:00', NULL, NULL, 'NOT_STARTED', 0, 0, 'Rattiya Janpum', '{"HVAC and pressure cascade balancing","Exhaust system performance test","Fire protection and safety system test","CAPEX equipment installation qualification","Operational qualification and user training"}', NULL, NULL, '2026-08-05 16:31:47.165'),
	('cmsgb180u001g7dqqc7urot76', 'cmsgb1803000j7dqq1hq49505', 6, 'Handover', '2026-11-23 00:00:00', '2026-12-06 00:00:00', NULL, NULL, 'NOT_STARTED', 0, 0, 'Warisa Kantifong', '{"Punch list closure","As-built drawing package","O&M manuals and warranty documents","Training completion records","Final handover certificate — 06 December 2026"}', NULL, NULL, '2026-08-05 16:31:47.167');
