INSERT INTO public."Risk" (id, "projectId", code, description, category, owner, likelihood, impact, level, "mitigationPlan", "dueDate", status, "escalationRequired", remarks, "updatedAt") VALUES
	('cmsgb184c006h7dqqfa51yn4h', 'cmsgb1803000j7dqq1hq49505', 'R-01', 'SEM-EDS purchase order not released in time — 30-week manufacturing lead time pushes delivery past the commissioning window and beyond the 06 Dec 2026 handover.', 'Equipment delivery', 'Rita Tang', 4, 5, 'CRITICAL', 'Escalated to leadership for a PO release decision by 08 Aug 2026. Vendor has confirmed a held production slot until 15 Aug 2026. Fallback: phase SEM-EDS into a post-handover installation window with a temporary analytical service agreement.', '2026-08-08 00:00:00', 'ESCALATED', true, 'Single largest schedule and CAPEX exposure on the project.', '2026-08-05 16:31:47.293'),
	('cmsgb184c006i7dqqbcuouyem', 'cmsgb1803000j7dqq1hq49505', 'R-02', 'Exhaust duct riser penetration through the INC2 building core is not yet endorsed by the landlord, blocking duct installation on the critical path.', 'Permit', 'Warisa Kantifong', 4, 4, 'HIGH', 'Structural opening calculation and fire-stopping detail submitted to the INC2 facility team. Weekly follow-up meeting established. Target endorsement 15 Aug 2026.', '2026-08-15 00:00:00', 'MITIGATING', true, 'Landlord technical review is in progress; no formal objection raised so far.', '2026-08-05 16:31:47.293'),
	('cmsgb184c006j7dqqo7vtmnbo', 'cmsgb1803000j7dqq1hq49505', 'R-03', 'Cleanroom and gas system design packages remain in Rev.B with open owner comments, delaying the full IFC release and payment milestone PM-02.', 'Design', 'Nattapong Wongsiri', 4, 4, 'HIGH', 'Design Alternative committed to Rev.C submission by 12 Aug 2026. SYME072 to provide a 5-working-day review turnaround. Daily design coordination call established.', '2026-08-20 00:00:00', 'MITIGATING', false, 'Blocks both PM-02 payment and the cleanroom / gas procurement packages.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006k7dqqdejf44fc', 'cmsgb1803000j7dqq1hq49505', 'R-04', 'Construction progress is 41% against a 50% plan; the seven-day late start has not yet been recovered.', 'Schedule', 'Nattapong Wongsiri', 4, 4, 'HIGH', 'Two-shift working approved for duct and MEP installation from 10 Aug 2026. Recovery schedule targets baseline alignment by 30 Sep 2026, reviewed weekly.', '2026-09-30 00:00:00', 'MITIGATING', true, 'No float remains ahead of the 06 Dec 2026 handover date.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006l7dqqlmzrumhp', 'cmsgb1803000j7dqq1hq49505', 'R-05', 'ICP-OES vendor data sheet outstanding, preventing the utility matrix and exhaust connection points from being frozen.', 'Design', 'Rattiya Janpum', 3, 4, 'HIGH', 'Formal request issued to the vendor with a 08 Aug 2026 deadline. Interim design assumption agreed with SYME072 so duct routing can proceed at risk.', '2026-08-08 00:00:00', 'OPEN', false, 'Interim assumption carries a rework exposure of roughly THB 180,000.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006m7dqqajvqgerl', 'cmsgb1803000j7dqq1hq49505', 'R-06', 'Laboratory furniture shop drawing approval slipping past 07 Aug 2026 would release the vendor production slot and add 4 weeks to delivery.', 'Procurement', 'Warisa Kantifong', 3, 3, 'MEDIUM', 'Laboratory user review workshop scheduled 05 Aug 2026 to close all comments in a single session.', '2026-08-07 00:00:00', 'MITIGATING', false, 'Vendor has confirmed the slot is held until 07 Aug 2026.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006n7dqqr3e4patt', 'cmsgb1803000j7dqq1hq49505', 'R-07', 'Hot work and overhead installation during two-shift working increases the risk of a lost-time injury in a live building.', 'Safety', 'Kanthima Sawatdee', 2, 5, 'HIGH', 'Permit-to-work for all hot work, night-shift EHS supervisor mandated, additional fire watch and daily toolbox talks for the second shift.', '2026-08-10 00:00:00', 'MITIGATING', false, 'Project has recorded zero LTI to date; controls tightened before shift change.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006o7dqqmuckbwng', 'cmsgb1803000j7dqq1hq49505', 'R-08', 'Design Alternative site supervision headcount is below the contract commitment during peak MEP installation.', 'Contractor performance', 'Warisa Kantifong', 3, 3, 'MEDIUM', 'Formal notice issued to Design Alternative. Manpower histogram to be submitted weekly and reviewed at the Monday progress meeting.', '2026-08-12 00:00:00', 'OPEN', false, 'Second notice; escalate to contractual remedy if unresolved by 12 Aug 2026.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006p7dqqilhfw166', 'cmsgb1803000j7dqq1hq49505', 'R-09', 'Cumulative change requests could exceed the 5% contingency held against the THB 48.5M contract value.', 'Budget', 'Rita Tang', 2, 4, 'MEDIUM', 'Change register reviewed fortnightly. Any change above THB 250,000 requires leadership approval before instruction.', '2026-09-15 00:00:00', 'OPEN', false, 'Contingency consumed to date: 1.8%.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006q7dqqc8khdcmp', 'cmsgb1803000j7dqq1hq49505', 'R-10', 'INC2 base-building chilled water capacity may be insufficient for the combined CSL HVAC and instrument cooling load at peak.', 'Utility readiness', 'Song Dong', 2, 4, 'MEDIUM', 'Load verification with the INC2 facility team scheduled for 20 Aug 2026. Dedicated chiller included in the supporting utility package as a contingency.', '2026-08-20 00:00:00', 'OPEN', false, 'Contingency chiller already priced within CAPEX-2026-020.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006r7dqq0juz00kt', 'cmsgb1803000j7dqq1hq49505', 'R-11', 'Laboratory operations require access to the adjacent working area during renovation, creating a containment and noise conflict.', 'Compliance', 'Rattiya Janpum', 3, 2, 'MEDIUM', 'Temporary dust partition installed, noisy activities restricted to 18:00–06:00, weekly coordination with laboratory operations.', '2026-08-29 00:00:00', 'MITIGATING', false, 'No operational complaint recorded in the last four weeks.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006s7dqqbn433va0', 'cmsgb1803000j7dqq1hq49505', 'R-12', 'Commissioning window compresses to under 4 weeks if mechanical completion slips beyond 13 Nov 2026.', 'Schedule', 'Rattiya Janpum', 3, 5, 'CRITICAL', 'Commissioning protocol to be approved by 12 Aug 2026 so pre-commissioning can start in parallel with the final MEP works. Vendor commissioning engineers to be booked by 30 Sep 2026.', '2026-09-30 00:00:00', 'OPEN', true, 'Directly threatens the 06 Dec 2026 handover commitment.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006t7dqq1ofrhn0f', 'cmsgb1803000j7dqq1hq49505', 'R-13', 'Temporary power distribution plan was rejected on EHS grounds and has not been resubmitted.', 'Safety', 'Nattapong Wongsiri', 2, 3, 'MEDIUM', 'Site currently operating on the INC2 permanent supply with an interim permit. Compliant plan required before the second shift starts.', '2026-08-09 00:00:00', 'OPEN', false, 'Resubmission overdue since 29 Jun 2026.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006u7dqqer56hdqx', 'cmsgb1803000j7dqq1hq49505', 'R-14', 'Import clearance delay for the Ion Chromatography shipment at Laem Chabang port.', 'Procurement', 'Rita Tang', 2, 2, 'LOW', 'Customs broker appointed and documentation pre-lodged. Buffer of 14 days held before the required-on-site date.', '2026-08-28 00:00:00', 'OPEN', false, 'Standard clearance risk, buffer available.', '2026-08-05 16:31:47.293'),
	('cmsgb184d006v7dqqd393d2v2', 'cmsgb1803000j7dqq1hq49505', 'R-15', 'Insufficient laboratory user availability for equipment training before handover.', 'Schedule', 'Rattiya Janpum', 2, 2, 'LOW', 'Training calendar issued to laboratory operations in advance; two training slots reserved per instrument.', '2026-10-30 00:00:00', 'OPEN', false, 'Training plan aligned with the vendor commissioning schedule.', '2026-08-05 16:31:47.293');
INSERT INTO public."SafetyReport" (id, "projectId", code, date, "reportedBy", description, category, severity, "correctiveAction", owner, "dueDate", status, "evidenceUrl", "updatedAt") VALUES
	('cmsgb184k006w7dqq3z7qbx7f', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-018', '2026-07-30 00:00:00', 'Kanthima Sawatdee', 'Housekeeping observation — offcut material accumulating in the corridor egress route outside the CSL entrance.', 'OBSERVATION', 'MEDIUM', 'Daily housekeeping sweep added to the end-of-shift checklist; dedicated waste skip positioned at the loading area.', 'Nattapong Wongsiri', '2026-08-04 00:00:00', 'IN_PROGRESS', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k006x7dqq0nhv4qu9', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-017', '2026-07-28 00:00:00', 'Rattiya Janpum', 'Near miss — unsecured ladder shifted while a worker was accessing the ceiling void for duct hanger installation. No injury.', 'NEAR_MISS', 'HIGH', 'Ladder inspection and tagging regime reinforced; mobile scaffold mandated for all work above 2 m. Toolbox talk delivered to all trades.', 'Kanthima Sawatdee', '2026-08-01 00:00:00', 'CLOSED', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k006y7dqqeutippez', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-016', '2026-07-24 00:00:00', 'Kanthima Sawatdee', 'Hot work permit audit — welding screen not deployed during duct bracket welding in zone C.', 'PERMIT_TO_WORK', 'HIGH', 'Permit suspended and reissued after screens deployed; fire watch briefing repeated for all welders.', 'Nattapong Wongsiri', '2026-07-26 00:00:00', 'CLOSED', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k006z7dqq56af22x1', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-015', '2026-07-21 00:00:00', 'Sarawut Thongchai', 'First aid case — minor hand laceration while handling a sheet metal duct section.', 'FIRST_AID', 'LOW', 'Cut-resistant gloves issued as mandatory PPE for all sheet metal handling; task risk assessment revised.', 'Nattapong Wongsiri', '2026-07-25 00:00:00', 'CLOSED', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k00707dqq29ucy0bf', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-014', '2026-07-17 00:00:00', 'Kanthima Sawatdee', 'Weekly joint safety inspection with the INC2 building EHS team. Two minor findings raised on temporary cable management.', 'INSPECTION', 'MEDIUM', 'Temporary cables re-routed at high level with dedicated hangers; interim RCD board relocated out of the walkway.', 'Nattapong Wongsiri', '2026-07-24 00:00:00', 'CLOSED', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k00717dqqs357vmz1', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-013', '2026-07-14 00:00:00', 'Nattapong Wongsiri', 'Toolbox talk — working at height and ladder safety, delivered to 24 site personnel.', 'TOOLBOX_TALK', 'LOW', 'Attendance register filed. Topic repeated for the incoming second shift.', 'Nattapong Wongsiri', '2026-07-14 00:00:00', 'CLOSED', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k00727dqqjfxvvutf', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-012', '2026-07-08 00:00:00', 'Kanthima Sawatdee', 'Observation — temporary power distribution board not compliant with the approved HSE plan (no RCD on two outlets).', 'OBSERVATION', 'HIGH', 'Board taken out of service and replaced. Compliant temporary power plan to be resubmitted by Design Alternative.', 'Nattapong Wongsiri', '2026-07-20 00:00:00', 'OVERDUE', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k00737dqq16py3enn', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-011', '2026-07-03 00:00:00', 'Rattiya Janpum', 'Observation — dust partition seal gap allowing construction dust into the adjacent operating laboratory.', 'OBSERVATION', 'MEDIUM', 'Partition sealed and a negative-pressure dust extractor installed inside the work area.', 'Nattapong Wongsiri', '2026-07-10 00:00:00', 'CLOSED', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k00747dqqa82g36lz', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-010', '2026-06-26 00:00:00', 'Kanthima Sawatdee', 'Near miss — material hoisting load swung close to a walkway that had not been barricaded.', 'NEAR_MISS', 'HIGH', 'Exclusion zone procedure enforced for all lifting; banksman assigned to every lift.', 'Nattapong Wongsiri', '2026-07-03 00:00:00', 'CLOSED', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k00757dqqm3jjto05', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-009', '2026-06-19 00:00:00', 'Kanthima Sawatdee', 'Monthly emergency response drill for the CSL renovation area, including evacuation route verification.', 'INSPECTION', 'LOW', 'Evacuation completed in 3 min 40 s. Assembly point signage improved.', 'Kanthima Sawatdee', '2026-06-26 00:00:00', 'CLOSED', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k00767dqqzve9nmdi', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-008', '2026-07-31 00:00:00', 'Kanthima Sawatdee', 'Pre-second-shift readiness inspection — night lighting levels in the work area below 200 lux in two zones.', 'INSPECTION', 'MEDIUM', 'Additional temporary lighting to be installed before the second shift commences on 10 Aug 2026.', 'Nattapong Wongsiri', '2026-08-08 00:00:00', 'OPEN', NULL, '2026-08-05 16:31:47.3'),
	('cmsgb184k00777dqqazwla2bn', 'cmsgb1803000j7dqq1hq49505', 'SR-2026-007', '2026-07-29 00:00:00', 'Nattapong Wongsiri', 'Toolbox talk — chemical handling and spill response ahead of laboratory gas line works.', 'TOOLBOX_TALK', 'LOW', 'Attendance register filed for 19 personnel.', 'Nattapong Wongsiri', '2026-07-29 00:00:00', 'CLOSED', NULL, '2026-08-05 16:31:47.3');
