	('cmsgb184v00817dqq2n4bcp8o', 'cmsgb1803000j7dqq1hq49505', 'ACT-122', 'Confirm the customs broker appointment and pre-lodge documents for the Ion Chromatography shipment.', 'Rita Tang', 'QNITY', '2026-07-28 00:00:00', 'MEDIUM', 'COMPLETED', 'Procurement Review — 21 Jul 2026', NULL, 'Broker appointed; documents lodged 27 Jul 2026.', '2026-08-05 16:31:47.31'),
	('cmsgb184v00827dqq3wa3q24y', 'cmsgb1803000j7dqq1hq49505', 'ACT-123', 'Evaluate the option of a dedicated chiller within the supporting utility package.', 'Song Dong', 'QNITY', '2026-08-15 00:00:00', 'LOW', 'OPEN', 'Utility Coordination — 22 Jul 2026', NULL, 'Priced within CAPEX-2026-020 as a contingency.', '2026-08-05 16:31:47.31'),
	('cmsgb184v00837dqqotu6cqma', 'cmsgb1803000j7dqq1hq49505', 'ACT-124', 'Reinstate the vendor portal account for the disabled equipment vendor representative.', 'Warisa Kantifong', 'QNITY', '2026-07-15 00:00:00', 'LOW', 'CANCELLED', 'Procurement Review — 07 Jul 2026', NULL, 'Cancelled — vendor representative left the supplier organisation.', '2026-08-05 16:31:47.31');
INSERT INTO public."OwnerAttentionItem" (id, "projectId", code, topic, description, category, "escalationReason", "requiredDecision", "recommendedAction", "decisionOwner", "requestedDecisionDate", "impactIfDelayed", "relatedRisk", "relatedMilestone", status, urgency, remarks, "updatedAt") VALUES
	('cmsgb185400847dqqmb6qer3a', 'cmsgb1803000j7dqq1hq49505', 'OA-01', 'Release SEM-EDS purchase order (THB 12.8M)', 'The SEM-EDS commercial evaluation is complete apart from a detector scope clarification. The vendor holds a manufacturing slot until 15 Aug 2026 against a 30-week lead time.', 'Long lead equipment issue', 'The purchase order exceeds the project manager''s delegated authority and the manufacturing slot expires within two weeks.', 'Approve release of the SEM-EDS purchase order at the evaluated value of THB 12.8M.', 'Approve the PO release by 08 Aug 2026 and accept the clarified EDS detector scope as evaluated by the laboratory engineering team.', 'Peiming Zhou', '2026-08-08 00:00:00', 'Delivery moves beyond the commissioning window. SEM-EDS would not be available for the 06 Dec 2026 handover and would require a post-handover installation with a temporary external analytical service.', 'R-01', 'MS-09', 'OPEN', 'RED', 'Highest priority decision on the project this month.', '2026-08-05 16:31:47.32'),
	('cmsgb185400857dqqjh4ge3b5', 'cmsgb1803000j7dqq1hq49505', 'OA-02', 'Approve payment milestone PM-02 release strategy (THB 9.7M)', 'Payment milestone PM-02 is tied to the full IFC drawing release. Eleven of fourteen design packages are approved; cleanroom and gas system packages remain in Rev.B.', 'Payment milestone approval', 'Design Alternative has requested a partial release against the approved disciplines. The contract does not provide for partial milestone payment.', 'Decide whether to hold PM-02 in full until complete IFC release, or approve a partial release of 70% against the approved packages.', 'Hold the milestone until the cleanroom and gas system Rev.C packages are approved (forecast 20 Aug 2026). Confirm in writing that no partial release will be made.', 'Samuel Chang', '2026-08-12 00:00:00', 'Contractor cash-flow pressure may reduce site manpower and worsen the existing construction schedule slippage.', 'R-03', 'MS-06', 'IN_REVIEW', 'YELLOW', 'Consultant recommendation supports holding the full milestone.', '2026-08-05 16:31:47.32'),
	('cmsgb185400867dqqc6cotoc5', 'cmsgb1803000j7dqq1hq49505', 'OA-03', 'Endorse the two-shift construction recovery plan', 'Construction stands at 41% against a 50% plan. Design Alternative proposes two-shift working for duct and MEP installation from 10 Aug 2026 to recover the schedule by 30 Sep 2026.', 'Schedule recovery decision', 'Two-shift working in a live building requires QNITY leadership endorsement and coordination with laboratory operations and the INC2 facility team.', 'Endorse two-shift working from 10 Aug 2026, including night-shift EHS supervision and restricted noisy activity hours.', 'Endorse subject to the temporary lighting and temporary power findings being closed and a night-shift EHS supervisor being named.', 'Peiming Zhou', '2026-08-07 00:00:00', 'Every week of delay in starting the second shift pushes mechanical completion beyond 13 Nov 2026 and compresses commissioning below four weeks.', 'R-04', 'MS-10', 'OPEN', 'RED', 'EHS pre-conditions tracked as ACT-107 and ACT-110.', '2026-08-05 16:31:47.32'),
	('cmsgb185400877dqqz6ckt89d', 'cmsgb1803000j7dqq1hq49505', 'OA-04', 'Landlord endorsement for the exhaust duct riser penetration', 'The exhaust riser penetration through the INC2 building core awaits landlord endorsement. Duct installation on the critical path cannot start without it.', 'Contract approval', 'Requires QNITY leadership engagement with the Thailand Science Park / INC2 building management at director level.', 'Authorise a formal QNITY approach to INC2 building management to expedite the endorsement, and confirm acceptance of any landlord reinstatement conditions.', 'Engineering Head to lead a joint technical session with the INC2 facility team in the week of 11 Aug 2026 with QNITY leadership sponsorship.', 'Song Dong', '2026-08-15 00:00:00', 'Exhaust duct installation stalls, blocking fume hood manufacturing release and mechanical completion.', 'R-02', 'MS-10', 'IN_REVIEW', 'RED', 'No formal landlord objection has been raised to date.', '2026-08-05 16:31:47.32'),
	('cmsgb185400887dqqg70qfe61', 'cmsgb1803000j7dqq1hq49505', 'OA-05', 'Award the supporting utility equipment package (THB 2.75M)', 'Technical evaluation of three quotations for DI water, chiller and compressed air equipment is nearing completion. Award is targeted for 15 Aug 2026.', 'Procurement decision', 'Award value exceeds the procurement lead''s delegated authority and includes the contingency chiller that addresses the INC2 chilled water capacity risk.', 'Approve award to the recommended vendor including the contingency dedicated chiller scope.', 'Approve at the 15 Aug 2026 procurement review once the chilled water capacity verification (ACT-112) is complete.', 'Rita Tang', '2026-08-15 00:00:00', 'A 16-week lead time places delivery beyond 09 Oct 2026 and into the commissioning window.', 'R-10', 'MS-11', 'OPEN', 'YELLOW', 'Chilled water verification session already booked.', '2026-08-05 16:31:47.32'),
	('cmsgb185400897dqqjffpzbkq', 'cmsgb1803000j7dqq1hq49505', 'OA-06', 'Design Alternative site supervision shortfall', 'Contractor site supervision headcount has been below the contract commitment for three consecutive weeks during peak MEP installation.', 'Contractor performance issue', 'Two formal notices have been issued without a sustained recovery. Contractual remedy requires leadership direction.', 'Decide whether to proceed to a contractual remedy if the manpower histogram is not met by 12 Aug 2026.', 'Issue a final written notice now, with a leadership-level meeting with the Design Alternative managing director in the week of 10 Aug 2026.', 'Samuel Chang', '2026-08-12 00:00:00', 'Supervision shortfall during two-shift working raises both quality and safety exposure.', 'R-08', NULL, 'OPEN', 'YELLOW', 'Tracked as ACT-108.', '2026-08-05 16:31:47.32'),
	('cmsgb1854008a7dqqyjpxzxzv', 'cmsgb1803000j7dqq1hq49505', 'OA-07', 'Approve the additional sample preparation bench change request', 'Laboratory users have requested an additional bench in the sample preparation room. Design Alternative is returning cost and schedule impact by 05 Aug 2026.', 'Change request', 'Any change above THB 250,000 requires leadership approval before instruction under the change control procedure.', 'Approve or reject the change once the contractor''s cost and schedule impact is received.', 'Approve only if the schedule impact is nil and the cost is within the remaining contingency (currently 3.2% of contract value available).', 'Samuel Chang', '2026-08-19 00:00:00', 'Instructing the change after the furniture production release would incur a change-of-order penalty from the vendor.', 'R-09', NULL, 'OPEN', 'YELLOW', 'Cost impact not yet received (ACT-113).', '2026-08-05 16:31:47.32'),
	('cmsgb1854008b7dqqjfkwwxwb', 'cmsgb1803000j7dqq1hq49505', 'OA-08', 'Temporary power compliance before second-shift start', 'The temporary power distribution plan was rejected on EHS grounds on 29 Jun 2026 and a compliant plan has not been resubmitted.', 'Safety decision', 'Overdue by more than one month and now a pre-condition for the two-shift recovery plan.', 'Confirm that the second shift will not start until a compliant temporary power plan is approved.', 'Confirm the EHS stop condition in writing to Design Alternative and link it to the two-shift endorsement in OA-03.', 'Warisa Kantifong', '2026-07-31 00:00:00', 'Starting a night shift on a non-compliant temporary supply would breach the approved HSE plan and QNITY EHS standards.', 'R-13', NULL, 'OVERDUE', 'RED', 'Decision date has passed — requires closure at the next leadership review.', '2026-08-05 16:31:47.32');
